cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// List all tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);

// Search for anything related to the booking
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\nTable:', t.name, '-> Columns:', cols.map(c => c.name).join(', '));

  // Check for booking or flight references
  try {
    const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 3').all();
    if (rows.length > 0) {
      console.log('Sample rows:', JSON.stringify(rows).substring(0, 500));
    }
  } catch(e) {}
}
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for the booking
const rows = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'BK-B70889'\").all();
console.log('Exact match:', JSON.stringify(rows, null, 2));

// Try partial match
const rows2 = db.prepare(\"SELECT booking_id, flight_id, cabin_class, seat_type, status, price_paid FROM flight_bookings WHERE booking_id LIKE '%B70889%' OR flight_id LIKE '%658038%'\").all();
console.log('Partial match:', JSON.stringify(rows2, null, 2));
"
